head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/mgt.js");
scwin.contnId;
scwin.notiObjSysCode;
scwin.vScrenID = "ULDSTF42040.gfm";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var KeyWord = keyword.value;

	//----W-Craft WebSquare 변환 확인: ValueOfIndex----//
    var Condition1 = MxCombo_1.ValueOfIndex("VALUE", MxCombo_1.getSelectedIndex());
    var Condition2 = MxDataSet_code1.getCellData((cb_system_gbn.getSelectedIndex() + 1), "CD_VAL");
    url = "/scren.do?method=listHelpContent";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&keyword=" + KeyWord;
    url += "&Condition1=" + Condition1;
    url += "&Condition2=" + Condition2;
    dts_noticeList.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_noticeList.reset();
    $c.cm.ShowWin(MxGrid_2);
};
scwin.fn_code1_sync = function() {
    var url1 = "/scren.do?method=searchTbmcCdval&inputMessageId=tbmccdval&outputMessageId=tbmccdval&CD_ENG_NM=NOTI_OBJ_SYS_TP_CD";
    MxDataSet_code1.DataID = encodeURI(url1);

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code1.reset();
};
scwin.fn_setContnId = function(obj) {
    if (scwin.contnId != "input") {
        scwin.contnId = dts_noticeList.getCellData(eval(obj), "SCREN_ID");
    }
};
scwin.fn_getContnId = function() {
    return scwin.contnId;
};
scwin.fn_setSysCode = function(obj) {
    scwin.notiObjSysCode = dts_noticeList.getCellData(eval(obj), "NOTI_OBJ_SYS_TP_CD");
};
scwin.fn_getSysCode = function() {
    return scwin.notiObjSysCode;
};
scwin.dts_noticeList_OnLoadCompleted = function(e) {
    $c.cm.CloseWin(rowcount, MxGrid_2); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.MxGrid_2_OnDblClick = async function(row, colid) {
    if (colid == 'SCREN_ID' || colid == 'MENU_NM') {
        scwin.contnId = dts_noticeList.getCellData(row, "SCREN_ID");

	//----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
        await $c.frame.CreateDialogFrame("gform", "ULDMGT42045.gfm", "도움말 상세", 200, 100, 660, 290, "window");
        scwin.fn_list_sync();
    } else if (colid == 'SAVE_FILE_NM') {
        var screnId = dts_noticeList.getCellData(row, "SCREN_ID");
        location.href = "/scren.do?method=downloadHelpFile&V_SCREN_ID=" + screnId;
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync();
    MxDataSet_code1.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbmccdval";

	//----W-Craft WebSquare 변환 확인: reset----//
    MxDataSet_code1.reset();
    scwin.fn_code1_sync();
    cb_system_gbn.Enable2 = true;
};
scwin.bnt_Select_onclick = function(e) {
    scwin.fn_list_sync();
};
scwin.btn_New_onclick = async function(e) {
    scwin.contnId = "input";

	//----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    await $c.frame.CreateDialogFrame("gform", "ULDMGT42045.gfm", "도움말 상세", 200, 100, 660, 290, "window");
    scwin.fn_list_sync();
};
scwin.keyword_onkeydown = function(e) {
    if (window.event.keyCode == "13") {
        scwin.fn_list_sync();
    }
};
